<template>

  <div>
    <h1>{{ pageTitleStrings.documentTitle$() }}</h1>
    <p>{{ description }}</p>
    <p>{{ $tr('hint') }}</p>
    <PasswordTextbox
      ref="passwordTextbox"
      data-testid="passwordTextbox"
      :value.sync="formData.password"
      :isValid.sync="isPasswordValid"
      :shouldValidate="isFormSubmitted"
    />

    <p :style="{ color: 'var(--tokens-annotation)' }">
      {{ coreString('rememberThisAccountInformation') }}
    </p>

    <BottomAppBar>
      <slot name="buttons">
        <KButtonGroup>
          <KButton
            :primary="false"
            :text="coreString('backAction')"
            appearance="flat-button"
            data-testid="backButton"
            @click="sendBack"
          />
          <KButton
            :primary="true"
            :text="coreString('continueAction')"
            data-testid="continueButton"
            :disabled="!isPasswordValid"
            @click="handleContinue"
          />
        </KButtonGroup>
      </slot>
    </BottomAppBar>
  </div>

</template>


<script>

  import { createTranslator } from 'kolibri/utils/i18n';
  import get from 'lodash/get';
  import commonCoreStrings from 'kolibri/uiText/commonCoreStrings';
  import usePageTitle from 'kolibri/composables/usePageTitle';
  import BottomAppBar from 'kolibri/components/BottomAppBar';
  import PasswordTextbox from 'kolibri-common/components/userAccounts/PasswordTextbox';
  import useUser from 'kolibri/composables/useUser';

  export const pageTitleStrings = createTranslator('CreatePassword', {
    documentTitle: {
      message: 'Create new password',
      context:
        'Title of the step for creating a new password for the user in the target facility when changing facility.',
    },
  });

  export default {
    name: 'CreatePassword',
    components: {
      BottomAppBar,
      PasswordTextbox,
    },
    mixins: [commonCoreStrings],
    inject: ['changeFacilityService', 'state'],
    setup() {
      usePageTitle(pageTitleStrings.documentTitle$, { hasVisibleHeading: true });
      const { session } = useUser();
      return { session, pageTitleStrings };
    },
    data() {
      return {
        formData: {
          password: '',
        },
        isPasswordValid: false,
        isFormSubmitted: false,
      };
    },
    computed: {
      description() {
        return this.$tr('description', {
          username: get(this.session, 'username', ''),
          targetFacility: get(this.state, 'targetFacility.name', ''),
        });
      },
    },
    methods: {
      handleContinue() {
        this.isFormSubmitted = true;
        if (this.isPasswordValid) {
          this.sendContinue();
        } else {
          this.$refs.passwordTextbox.focus();
        }
      },
      sendContinue() {
        this.changeFacilityService.send({
          type: 'CONTINUE',
          value: {
            username: get(this.state, 'targetAccount.username', ''),
            password: this.formData.password,
          },
        });
      },
      sendBack() {
        this.changeFacilityService.send({
          type: 'BACK',
        });
      },
    },
    $trs: {
      description: {
        message:
          '‘{targetFacility}’ requires accounts to have passwords. Enter a password that you would like to use for ‘{username}’ in ‘{targetFacility}’',
        context: 'Explains why a password must be created.',
      },
      hint: {
        message: 'You can enter your current password if you already have one.',
      },
    },
  };

</script>
